import { test } from 'node:test';
import assert from 'node:assert/strict';
import { total, itemCount } from '../src/cart.js';

test('total without discount', () => {
  assert.equal(total([{ price: 100, qty: 2 }, { price: 50, qty: 1 }]), 250);
});

// issue #12: the customer discount must be applied exactly once.
const lines = (n, price) => Array.from({ length: n }, () => ({ price, qty: 1 }));

test('customer discount is applied once (fewer than 10 lines)', () => {
  // 1,000 less 10% = 900
  assert.equal(total([{ price: 1000, qty: 1 }], 0.1), 900);
});

test('bulk discount is applied once, after the customer discount (10 lines)', () => {
  // 10,000 less 10% = 9,000; less 5% bulk = 8,550
  assert.equal(total(lines(10, 1000), 0.1), 8550);
});

test('no bulk discount below 10 lines (9 lines)', () => {
  // 9,000 less 10% = 8,100; no bulk discount
  assert.equal(total(lines(9, 1000), 0.1), 8100);
});

test('discount rate 0 with 10 lines keeps only the bulk discount', () => {
  // 10,000 less 5% bulk = 9,500 (unchanged by the issue #12 fix)
  assert.equal(total(lines(10, 1000), 0), 9500);
  assert.equal(total(lines(10, 1000)), 9500);
});

test('item count', () => {
  assert.equal(itemCount([{ price: 1, qty: 3 }, { price: 1, qty: 2 }]), 5);
});
